 function applyText(node){const current=normalize(node.nodeValue);if(!current)return;const old=texts.get(node),source=canonical(current,old),target=translated(source);if(target===null){recordMissing(source,node);return;}const prefix=node.nodeValue.match(/^\s*/u)?.[0]||'',suffix=node.nodeValue.match(/\s*$/u)?.[0]||'';const value=prefix+target+suffix;texts.set(node,{source,last:normalize(value)});assignText(node,value);}
