 async function setLanguage(lang,{persist=true}={}){if(disposed||!LANGS.includes(lang))return false;const request=++epoch;translating=true;status(say('loading'));try{await loadLanguage(lang);if(disposed||request!==epoch)return false;stopVoice();captureAnswer();language=lang;root.lang=lang;root.dataset.language=lang;if(learningTarget===lang)learningTarget=lang==='fr'?'en':'fr';scan();addDialogControls();if(dialog?.open){await updateReadingPair();renderLearning();}const persisted=persist?persistPreference():true;status(!persisted?say('storageError'):untranslatedProse.size?say('partial'):'',persisted?'coverage':'notice');emitLanguage();return true;}catch{if(request===epoch&&!disposed)status(say('loadError'));return false;}finally{if(request===epoch)translating=false;}}
 function readReview(){if(reviewLoaded)return;reviewLoaded=true;try{const raw=localStorage.getItem(LEARNING);if(!raw)return;if(raw.length>200000)throw Error();const value=JSON.parse(raw);if(value?.version!==1||!value.phrases||typeof value.phrases!=='object'||Array.isArray(value.phrases))throw Error();review={version:1,phrases:{}};for(const[id,item]of Object.entries(value.phrases)){if(/^[a-z0-9-]+$/.test(id)&&item&&typeof item==='object')review.phrases[id]={saved:item.saved===true,reviewed:item.reviewed===true};}if(LANGS.includes(value.target))learningTarget=value.target;}catch{try{corruptRaw=localStorage.getItem(LEARNING);}catch{}status(say('corrupt'));}}
