 const validLessons=raw=>raw?.version===1&&Array.isArray(raw.phrases)?raw.phrases.filter(p=>p&&/^[a-z0-9-]+$/.test(p.id)&&['city','graffiti','studio','freestyle','philosophy'].includes(p.topic)&&LANGS.every(lang=>typeof p[lang]==='string'&&p[lang].trim().length>2)):[];
