 function renderLearning(){if(!dialog||!lessons)return;const all=currentPhrases();if(!all.length){topic='all';card=0;return renderLearning();}card=(card+all.length)%all.length;const phrase=all[card],entry=review.phrases[phrase.id]||{},saved=Object.values(review.phrases).filter(p=>p.saved).length,reviewed=Object.values(review.phrases).filter(p=>p.reviewed).length;dialog.lang=language;dialog.innerHTML=`<div class="language-dialog-top"><p>CAISIK / ${escape(say('learning'))}</p><button type="button" data-close-language-learning aria-label="${escape(say('close'))}">×</button></div><h2>${escape(say('learning'))}</h2><p class="language-intro">${escape(say('intro'))}</p>${readingPair?`<section class="language-reading-pair"><p class="language-counter">${escape(readingSay('title'))}</p><p lang="${escape(readingPair.sourceLang)}">${escape(readingPair.source)}</p><p lang="${escape(readingPair.targetLang)}" class="language-target">${escape(readingPair.target)}</p><button type="button" data-reading-listen>${escape(readingSay('listen'))}</button><button type="button" data-reading-clear>${escape(readingSay('clear'))}</button></section>`:''}<div class="language-learning-controls"><label>${escape(say('source'))}<select data-learning-base>${LANGS.map(lang=>`<option value="${lang}" ${language===lang?'selected':''}>${names[lang]}</option>`).join('')}</select></label><label>${escape(say('target'))}<select data-learning-target>${LANGS.map(lang=>`<option value="${lang}" ${learningTarget===lang?'selected':''}>${names[lang]}</option>`).join('')}</select></label><label>${escape(say('topic'))}<select data-learning-topic>${['all','city','graffiti','studio','freestyle','philosophy'].map(value=>`<option value="${value}" ${topic===value?'selected':''}>${escape(say(value))}</option>`).join('')}</select></label></div><p class="language-counter">${card+1} / ${all.length} · ${escape(say('counter'))} · ${saved} ${escape(say('savedCount'))} · ${reviewed} ${escape(say('reviewCount'))}</p><section class="language-phrase"><p class="language-source" lang="${language}" data-learning-source>${escape(phrase[language])}</p><p class="language-target" lang="${learningTarget}" data-learning-translation ${revealed?'':'hidden'}>${escape(phrase[learningTarget])}</p><button type="button" data-learning-reveal>${escape(say(revealed?'hide':'reveal'))}</button><div class="language-pronunciation"><button type="button" data-learning-listen>${escape(say('listen'))}</button><button type="button" data-learning-stop>${escape(say('stop'))}</button></div></section><label class="language-recall-label" for="caisik-language-answer">${escape(say('prompt'))}</label><input id="caisik-language-answer" data-learning-answer type="text" maxlength="500" autocomplete="off" spellcheck="true" lang="${learningTarget}"><button type="button" class="language-primary" data-learning-check>${escape(say('check'))}</button><p data-learning-feedback class="language-feedback" role="status"></p><div class="language-card-actions"><button type="button" data-learning-prev>${escape(say('prev'))}</button><button type="button" data-learning-next>${escape(say('next'))}</button><button type="button" data-learning-save aria-pressed="${entry.saved===true}">${escape(say(entry.saved?'unsave':'save'))}</button><button type="button" data-learning-reviewed aria-pressed="${entry.reviewed===true}">${escape(say('reviewed'))}</button></div><p data-learning-status role="status">${corruptRaw!==null?escape(say('corrupt')):''}</p><p class="language-privacy">${escape(say('privacy'))}</p><div class="language-data-actions"><button type="button" data-learning-export>${escape(say('export'))}</button><button type="button" data-learning-reset>${escape(say('reset'))}</button></div><div class="language-reset-confirm" data-learning-confirm hidden><p>${escape(say('confirm'))}</p><button type="button" data-learning-confirm-reset>${escape(say('yes'))}</button><button type="button" data-learning-cancel-reset>${escape(say('cancel'))}</button></div>`;dialog.querySelector('[data-learning-answer]').value=answer;}
 async function openLearning(){if(disposed)return;stopVoice();if(!dialog){dialog=doc.createElement('dialog');dialog.id='caisik-language-dialog';dialog.className='language-dialog';dialog.setAttribute('data-language-ui','');dialog.setAttribute('data-text-motion','off');dialog.setAttribute('aria-label',say('learning'));doc.body.append(dialog);listen(dialog,'close',()=>{captureAnswer();stopVoice();});}dialog.innerHTML=`<p role="status">${escape(say('loading'))}</p><button type="button" data-close-language-learning aria-label="${escape(say('close'))}">×</button>`;if(!dialog.open){if(dialog.showModal)dialog.showModal();else dialog.setAttribute('open','');}try{await loadLessons();if(!disposed&&dialog.open){readReview();if(learningTarget===language)learningTarget=language==='fr'?'en':'fr';await updateReadingPair();renderLearning();}}catch{if(dialog?.open)dialog.innerHTML=`<p role="status">${escape(say('lessonError'))}</p><button type="button" data-close-language-learning>${escape(say('close'))}</button>`;}}
 function stopVoice(){try{window.speechSynthesis?.cancel();}catch{}}
 function speak(text=currentPhrase()?.[learningTarget],lang=learningTarget){const synth=window.speechSynthesis;if(!text)return;stopVoice();const voice=synth?.getVoices?.().find(v=>v.localService===true&&String(v.lang).toLowerCase().split('-')[0]===lang);if(!voice||typeof window.SpeechSynthesisUtterance!=='function'){learningStatus(say('voiceMissing'));return;}try{const utterance=new window.SpeechSynthesisUtterance(text);utterance.voice=voice;utterance.lang=voice.lang;utterance.rate=.88;utterance.onerror=()=>learningStatus(say('voiceError'));synth.speak(utterance);learningStatus(say('voiceReading'));}catch{learningStatus(say('voiceError'));}}
 function normalizedAnswer(value,dropAccents=false){let result=normalize(value).toLocaleLowerCase().replace(/[’`]/g,"'").replace(/[.,!?;:«»„“”"']/gu,'').replace(/\s+/gu,' ').trim();if(dropAccents)result=result.normalize('NFD').replace(/[\u0300-\u036f]/g,'');return result;}
 function compareAnswer(){captureAnswer();const phrase=currentPhrase(),feedback=dialog.querySelector('[data-learning-feedback]');if(!normalize(answer)){feedback.textContent=say('empty');return;}revealed=true;const target=dialog.querySelector('[data-learning-translation]');target.hidden=false;dialog.querySelector('[data-learning-reveal]').textContent=say('hide');feedback.textContent=normalizedAnswer(answer)===normalizedAnswer(phrase[learningTarget])?say('correct'):normalizedAnswer(answer,true)===normalizedAnswer(phrase[learningTarget],true)?say('accent'):say('compare');}
 function exportReview(){const output={project:'CAISIK / Language practice',version:1,exportedAt:new Date().toISOString(),language,target:learningTarget,practice:review,...(corruptRaw!==null?{retainedInvalidOriginal:corruptRaw}:{})};const url=URL.createObjectURL(new Blob([JSON.stringify(output,null,2)],{type:'application/json'}));const a=doc.createElement('a');a.href=url;a.download='caisik-language-practice.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);learningStatus(say('exported'));}
 function changeCard(direction){stopVoice();answer='';revealed=false;card+=direction;renderLearning();dialog.querySelector('[data-learning-source]')?.focus?.();}
 function handleClick(event){const button=event.target.closest?.('button');if(!button)return;if(button.dataset.setLanguage){setLanguage(button.dataset.setLanguage);return;}if(button.hasAttribute('data-reading-toggle')){readingMode=!readingMode;if(!readingMode)selectedPublicText=null;syncControls();persistPreference();return;}if(button.hasAttribute('data-read-selection')){compareSelection();return;}if(button.hasAttribute('data-open-language-learning')){openLearning();return;}if(!dialog?.contains(button))return;if(button.hasAttribute('data-close-language-learning')){stopVoice();if(dialog.close)dialog.close();else dialog.removeAttribute('open');}else if(button.hasAttribute('data-learning-reveal')){captureAnswer();revealed=!revealed;const target=dialog.querySelector('[data-learning-translation]');target.hidden=!revealed;button.textContent=say(revealed?'hide':'reveal');}else if(button.hasAttribute('data-reading-listen')){if(readingPair)speak(readingPair.target,readingPair.targetLang);}else if(button.hasAttribute('data-reading-clear')){stopVoice();readingPair=null;renderLearning();}else if(button.hasAttribute('data-learning-listen'))speak();else if(button.hasAttribute('data-learning-stop'))stopVoice();else if(button.hasAttribute('data-learning-check'))compareAnswer();else if(button.hasAttribute('data-learning-next'))changeCard(1);else if(button.hasAttribute('data-learning-prev'))changeCard(-1);else if(button.hasAttribute('data-learning-save')||button.hasAttribute('data-learning-reviewed')){captureAnswer();const id=currentPhrase().id,entry=review.phrases[id]||{saved:false,reviewed:false};if(button.hasAttribute('data-learning-save'))entry.saved=!entry.saved;else entry.reviewed=!entry.reviewed;review.phrases[id]=entry;const okay=saveReview();renderLearning();learningStatus(okay?say(button.hasAttribute('data-learning-save')?'saved':'reviewDone'):say(corruptRaw!==null?'corrupt':'storageError'));}else if(button.hasAttribute('data-learning-export'))exportReview();else if(button.hasAttribute('data-learning-reset'))dialog.querySelector('[data-learning-confirm]').hidden=false;else if(button.hasAttribute('data-learning-cancel-reset'))dialog.querySelector('[data-learning-confirm]').hidden=true;else if(button.hasAttribute('data-learning-confirm-reset')){try{localStorage.removeItem(LEARNING);corruptRaw=null;review={version:1,phrases:{}};renderLearning();learningStatus(say('resetDone'));}catch{learningStatus(say('storageError'));}}}
 async function handleChange(event){if(event.target.matches('[data-learning-base]')){captureAnswer();setLanguage(event.target.value);}else if(event.target.matches('[data-learning-target]')){captureAnswer();const target=event.target.value;if(target===language){learningStatus(say('same'));event.target.value=learningTarget;return;}stopVoice();learningTarget=target;revealed=false;answer='';const okay=saveReview();await updateReadingPair();renderLearning();if(!okay)learningStatus(say(corruptRaw!==null?'corrupt':'storageError'));}else if(event.target.matches('[data-learning-topic]')){stopVoice();topic=event.target.value;card=0;answer='';revealed=false;renderLearning();}}
 function captureSelection(){if(!readingMode)return false;const selection=window.getSelection?.();if(!selection||selection.isCollapsed||!selection.rangeCount)return false;const anchor=selection.anchorNode?.nodeType===1?selection.anchorNode:selection.anchorNode?.parentElement,focus=selection.focusNode?.nodeType===1?selection.focusNode:selection.focusNode?.parentElement;const publicSelector='main,#profile-content,.exp-shell,.play-shell';if(!anchor?.closest?.(publicSelector)||!focus?.closest?.(publicSelector)||anchor.closest(skip)||focus.closest(skip)){selectedPublicText=null;return false;}let range;try{range=selection.getRangeAt(0);const common=range.commonAncestorContainer?.nodeType===1?range.commonAncestorContainer:range.commonAncestorContainer?.parentElement;if(common?.querySelectorAll&&range.intersectsNode){for(const protectedNode of common.querySelectorAll(privateContent))if(range.intersectsNode(protectedNode)){selectedPublicText=null;return false;}}}catch{selectedPublicText=null;return false;}const text=normalize(selection.toString());if(text.length<3||text.length>8000){selectedPublicText=null;return false;}const host=anchor.closest('p,h1,h2,h3,h4,li,span,section,article')||anchor;selectedPublicText={text,host,sourceLang:host.closest('[lang]')?.getAttribute('lang')||language};return true;}
 async function updateReadingPair(){if(!readingPair||readingPair.targetLang===learningTarget)return true;const request=++pairEpoch,targetLang=learningTarget;try{await loadLanguage(targetLang);if(disposed||request!==pairEpoch)return false;const value=translated(readingPair.canonical||canonical(normalize(readingPair.source)),targetLang);if(value===null){readingPair=null;learningStatus(readingSay('missing'));return false;}readingPair={...readingPair,target:value,targetLang};return true;}catch{readingPair=null;learningStatus(say('loadError'));return false;}}
 async function compareSelection(){if(disposed||!readingMode)return false;captureSelection();const selected=selectedPublicText;if(!selected||!selected.host.isConnected){status(readingSay('empty'));return false;}readReview();if(learningTarget===language)learningTarget=language==='fr'?'en':'fr';try{await loadLanguage(learningTarget);if(disposed)return false;const current=normalize(selected.text),source=canonical(current,elements.get(selected.host)),target=translated(source,learningTarget);if(target===null){status(readingSay('missing'));return false;}readingPair={source:selected.text,canonical:source,sourceLang:selected.sourceLang,target,targetLang:learningTarget};await openLearning();return true;}catch{status(say('loadError'));return false;}}
 function destroy(){if(disposed)return;disposed=true;++epoch;observer?.disconnect();listeners.forEach(remove=>remove());stopVoice();dock?.remove();dialog?.remove();doc.querySelectorAll('[data-language-inline]').forEach(node=>node.remove());root.classList.remove('has-language-dock','language-reading-on');if(window.CaisikI18n===api)delete window.CaisikI18n;}
 language=readPreference();
 dock=doc.createElement('aside');dock.className='language-dock';dock.setAttribute('data-language-dock','');dock.setAttribute('data-language-ui','');dock.setAttribute('data-text-motion','off');dock.setAttribute('aria-label',say('switch'));dock.innerHTML=switcher();doc.body.append(dock);root.classList.add('has-language-dock');
 listen(doc,'selectionchange',captureSelection);listen(doc,'click',handleClick);listen(doc,'change',handleChange);listen(doc,'input',event=>{if(event.target.matches('[data-learning-answer]'))answer=event.target.value;});
 listen(doc,'visibilitychange',()=>{if(doc.hidden)stopVoice();});listen(window,'pagehide',event=>{stopVoice();if(!event.persisted)destroy();});listen(window,'pageshow',()=>{if(!disposed){addDialogControls();schedule();}});
 if(window.speechSynthesis?.addEventListener)listen(window.speechSynthesis,'voiceschanged',()=>{if(dialog?.open)learningStatus('');});
 function observeBody(){if(observer&&!disposed)observer.observe(doc.body,{childList:true,subtree:true,characterData:true,attributes:true,attributeFilter:['aria-label','title','placeholder','alt','open']});}
 if(typeof MutationObserver==='function'){observer=new MutationObserver(records=>{if(disposed||applying)return;let relevant=false;for(const record of records){const target=record.target.nodeType===3?record.target.parentElement:record.target;if(target?.closest?.('[data-language-ui]'))continue;if(record.type==='attributes'&&record.attributeName==='open')addDialogControls();if(record.type==='characterData'||record.type==='childList'||['aria-label','title','placeholder','alt','open'].includes(record.attributeName))relevant=true;}if(relevant)schedule();});observeBody();}
